"""Install the sdkconfig-specific sections.ld generated by pioarduino's IDF phase.

With `custom_sdkconfig`, pioarduino rebuilds the ESP-IDF libraries and copies the
`.a` files and memory.ld into framework-arduinoespressif32-libs, but not the
generated sections.ld. The Arduino link then keeps using the prebuilt linker
script, so every Kconfig option implemented through linker fragments is silently
ignored: CONFIG_PM_SLP_IRAM_OPT, CONFIG_PM_RTOS_IDLE_OPT, *_IN_IRAM, etc.
(On the X4 Pro, esp_light_sleep_start and the idle/sleep path stayed in flash.)

This post: script copies $BUILD_DIR/sections.ld into the memory-type folder the
Arduino link uses as soon as the IDF phase generates it, before pioarduino
deletes the build directory. In the Arduino phase there is no sections.ld target
and the script does nothing.
"""

import shutil
from pathlib import Path

Import("env")


def install_sections_ld(target, source, env):
    libs_dir = env.PioPlatform().get_package_dir("framework-arduinoespressif32-libs")
    if not libs_dir:
        print("sections.ld install skipped: framework-arduinoespressif32-libs not found.")
        return
    board = env.BoardConfig()
    mcu = board.get("build.mcu", "esp32s3")
    memory_type = board.get("build.arduino.memory_type", board.get("build.flash_mode", "dio") + "_qspi")
    # Chips without a memory-type folder (e.g. esp32c3) keep sections.ld in ld/.
    destination_dir = Path(libs_dir) / mcu / memory_type
    if not (destination_dir / "sections.ld").exists():
        destination_dir = Path(libs_dir) / mcu / "ld"
    shutil.copy2(str(target[0]), str(destination_dir / "sections.ld"))
    print(f"*** Installed generated sections.ld into {destination_dir} ***")


sections_ld = env.File(str(Path(env.subst("$BUILD_DIR")) / "sections.ld"))
if sections_ld.has_builder():
    env.AddPostAction(sections_ld, install_sections_ld)
